create table if not exists template_registry.package_versions (id text primary key, tenant_id text not null, environment text not null, livemode boolean not null, dar_upload_id text not null references template_registry.dar_uploads(id), template_family text not null, operation_type text not null, package_id text not null, package_version text not null, registry_version integer not null default 1, status template_registry.package_status not null default 'registered', published_by text, approved_by text, active_from timestamptz, retired_at timestamptz, created_at timestamptz not null default now(), check (published_by is null or approved_by is null or published_by <> approved_by));
create unique index if not exists package_versions_active_idx on template_registry.package_versions(tenant_id,environment,livemode,template_family,operation_type) where status='active';
create index if not exists package_versions_lookup_idx on template_registry.package_versions(tenant_id,environment,livemode,template_family,operation_type,package_version);
-- verify: select 1 from information_schema.tables where table_schema='template_registry' and table_name='package_versions';
